var data = JSON.parse(msg.payload);

// Fonction de classification des alertes
function classify(value, normalMin, normalMax, critMin, critMax){
    if(value < critMin || value > critMax){ return 'Critique'; }
    if(value < normalMin || value > normalMax){ return 'Attention'; }
    return 'Normal';
}

// Calcul des alertes individuelles
var alertBpm = classify(data.bpm, 60, 100, 50, 120);
var alertTemp = classify(data.temperature, 36.5, 37.5, 36, 38.5);
var alertSpo2 = classify(data.spo2, 95, 100, 92, 100);
var alertTension = classify(data.systolic, 110, 130, 90, 160);

// Détermination du statut global du patient
var globalStatus = 'Normal';
if(alertBpm === 'Critique' || alertTemp === 'Critique' || alertSpo2 === 'Critique' || alertTension === 'Critique') {
    globalStatus = 'Critique';
} else if(alertBpm === 'Attention' || alertTemp === 'Attention' || alertSpo2 === 'Attention' || alertTension === 'Attention') {
    globalStatus = 'Attention';
}

// FORMATAGE ADAPTÉ POUR INFLUXDB (Mesures numériques + Index textuels)
msg.measurement = "sante_patients";
msg.payload = {
    fields: {
        bpm: data.bpm,
        temperature: data.temperature,
        spo2: data.spo2,
        systolic: data.systolic,
        diastolic: data.diastolic
    },
    tags: {
        patient_id: data.patient_id || "Inconnu",
        statut_global: globalStatus,
        alerte_bpm: alertBpm,
        alerte_temp: alertTemp,
        alerte_spo2: alertSpo2,
        alerte_tension: alertTension

    },
    timestamp: Date.now()
};

return msg;
